const WELCOME_IMAGE = "data:image/jpeg;base64,";
function intro(day){
 return '<section class="intro">'+'<img src="' + WELCOME_IMAGE + '" alt="فيلا في مسقط">'+'<div class="intro-copy"><div class="rule"></div><p class="brandline" lang="en">Middle East Properties Global'+(day?'':' S.P.C.')+'</p>'+
 (day?'<h1><bdi lang="en">Welcome Back</bdi><span>مرحبًا بعودتك</span></h1><p lang="en" dir="ltr" style="text-align:right">Explore the latest available villas</p><p>اطّلع على أحدث الفلل المتاحة</p><button class="primary" data-accept><bdi>View Latest Updates | عرض آخر التحديثات</bdi></button>':'<h1>'+bilingual('مرحبًا بك في منصة الفلل','Welcome to the Villas Platform')+'</h1><p>'+label('تصفّح الفلل المتاحة للإيجار في مسقط.','Explore villas available for rent in Muscat.')+'</p><button class="primary" data-accept>'+label('تفعيل الوصول','Activate Access')+'</button>')+'</div></section>';
}
const screen = document.querySelector('#screen');
const option = document.body.dataset.option === 'b' ? 'b' : 'a';
const escape = value => String(value ?? '').replace(/[&<>"']/g, char =>
  ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'})[char]);
const bilingual = (ar, en) => escape(ar) + (en ? '<span lang="en" dir="ltr">' + escape(en) + '</span>' : '');
const label = (ar, en) => escape(ar) + (en ? '<small lang="en" dir="ltr">' + escape(en) + '</small>' : '');
const nav = (page, ar, en, id = '', primary = false) =>
  '<button type="button" class="btn ' + (primary ? 'primary' : '') + '" data-page="' +
  page + '" data-id="' + escape(id) + '">' + label(ar, en) + '</button>';
let token = '';
let busy = false;
let pendingHistory = null;
let currentRoute = null;
let generation = 0;
let detailVilla = null;
let photo = 0;

const API_URL = 'https://script.google.com/macros/s/AKfycbyk3kpvv6Q5Zn2H1r9-RE1T7ybOojS0jUn9iHt7KohALcqwyVKy0cO3vHOOA2vqbW_m_Q/exec';

async function rpc(action, ...args) {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers: {'Content-Type': 'text/plain;charset=UTF-8'},
    body: JSON.stringify({action, token, args}),
    credentials: 'omit',
    redirect: 'follow',
    referrerPolicy: 'no-referrer'
  });
  if (!response.ok) throw new Error('Request failed');
  const result = await response.json();
  if (result.state === 'error') throw new Error('Service error');
  return result;
}

function render(html) {
  generation++;
  screen.className = 'option-' + option;
  screen.innerHTML = html;
  screen.focus({preventScroll:true});
  window.scrollTo(0, 0);
}

function empty(ar, en, body = '') {
  render('<section class="empty"><h1>' + bilingual(ar, en) + '</h1>' + body + '</section>');
}

function statePage(state) {
  detailVilla = null;
  if (state === 'first' || state === 'renew') return render(intro(state === 'renew'));
  if (state === 'missing') return empty('الفيلا غير متاحة', 'Villa unavailable',
    nav('areas','المناطق','Areas'));
  empty('تعذّر فتح الرابط', 'This link could not be opened',
    '<p>' + label('يرجى التواصل مع الشركة للحصول على المساعدة.', 'Please contact the company for assistance.') + '</p>');
}

function heading(villa) {
  return bilingual(villa.title || villa.area, villa.titleEn || villa.areaEn);
}
function areaText(ar, en) {
  return escape([ar, en].filter(Boolean).join(' · '));
}
function money(villa) {
  if (villa.rent === '') return '';
  const amount = Number(villa.rent);
  const rent = Number.isFinite(amount) ? amount.toLocaleString('en', {maximumFractionDigits:3}) : villa.rent;
  return '<div class="price">' + escape(rent) + ' ر.ع. <small lang="en">OMR / month · الإيجار الشهري</small></div>';
}
function specs(villa) {
  const fields = [
    villa.beds === '' ? '' : label(villa.beds + ' غرف نوم', villa.beds + ' bedrooms'),
    villa.baths === '' ? '' : label(villa.baths + ' حمامات', villa.baths + ' bathrooms'),
    label(villa.specs, villa.specsEn),
    villa.parking === '' ? '' : label(villa.parking + ' مواقف سيارات', villa.parking + ' parking spaces')
  ];
  return '<div class="specs">' + fields.filter(Boolean).map(value => '<span>' + value + '</span>').join('') + '</div>';
}
function crumb(area) {
  return '<nav class="crumb" aria-label="العودة">' + nav('areas','المناطق','Areas') +
    (area ? nav('list','قائمة الفلل','Villas',area) : '') + '</nav>';
}

function areasPage(areas) {
  detailVilla = null;
  render('<h1>' + bilingual('اختر المنطقة', 'Choose an area') + '</h1><div class="grid areas">' +
    (areas.length ? areas.map(area =>
      '<button class="area" data-page="list" data-id="' + escape(area.ar) + '"><strong>' +
      bilingual(area.ar, area.en) + '</strong><span>' + escape(area.count) + ' · ' +
      label('فلل متاحة','Available villas') + '</span></button>').join('') :
      '<div class="empty">' + bilingual('لا توجد فلل متاحة حاليًا','No villas currently available') + '</div>') + '</div>');
}

function photoSlot(villa, index, classes, alt) {
  return '<span class="photo-slot ' + classes + '" data-villa="' + escape(villa.id) +
    '" data-index="' + index + '"><img hidden alt="' + escape(alt) +
    '"><span class="photo-fallback">جارٍ تحميل الصورة… · Loading image…</span></span>';
}
function listPage(area, villas) {
  detailVilla = null;
  render(crumb() + '<h1>' + bilingual(area, villas[0]?.areaEn) + '</h1><div class="grid cards">' +
    (villas.length ? villas.map(villa => '<article class="card">' +
      photoSlot(villa, 0, 'photo', villa.title || villa.area) + '<div class="card-copy"><small>' +
      areaText(villa.area, villa.areaEn) + '</small><h2>' + heading(villa) + '</h2>' +
      money(villa) + specs(villa) + nav('villa','عرض التفاصيل','View villa',villa.id,true) +
      '</div></article>').join('') : '<div class="empty"><h2>' +
      bilingual('لا توجد فلل متاحة حاليًا','No villas currently available') + '</h2>' +
      nav('areas','اختر منطقة أخرى','Choose another area') + '</div>') + '</div>');
  hydratePhotos();
}

function details(villa) {
  detailVilla = villa;
  photo = 0;
  const count = villa.photoCount;
  const controls = count > 1 ? '<div class="gallery-actions">' +
    '<button type="button" data-step="-1" aria-label="الصورة السابقة">‹</button>' +
    '<span id="photo-count" aria-live="polite" dir="ltr">1 / ' + count + '</span>' +
    '<button type="button" data-step="1" aria-label="الصورة التالية">›</button></div>' +
    '<div class="thumbs">' + Array.from({length:count}, (_, index) =>
      '<button type="button" data-photo="' + index + '" aria-label="صورة ' + (index + 1) +
      '" aria-pressed="' + (index === 0) + '">' + photoSlot(villa,index,'thumb','') + '</button>').join('') + '</div>' : '';
  render(crumb(villa.area) + '<h1>' + heading(villa) + '</h1><p>' + areaText(villa.area,villa.areaEn) +
    '</p><div class="detail-grid"><figure class="gallery"><div id="hero">' +
    (count ? photoSlot(villa,0,'hero','صورة الفيلا') :
      '<span class="hero photo-slot">الصورة غير متاحة · Image unavailable</span>') +
    '</div>' + controls + '</figure><section class="details-copy">' +
    money(villa) + specs(villa) + '<p>' + label(villa.description, villa.descriptionEn) + '</p>' +
    nav('list','العودة إلى القائمة','Back to villas',villa.area) + '</section></div>');
  hydratePhotos();
}

const photoRequests = new Map();
function hydratePhotos(scope = screen) {
  const view = generation;
  const load = async slot => {
    const id = slot.dataset.villa;
    const index = Number(slot.dataset.index);
    const key = JSON.stringify([view,id,index]);
    try {
      if (!photoRequests.has(key)) {
        photoRequests.set(key, rpc('villaPhoto', id, index).finally(() => photoRequests.delete(key)));
      }
      const result = await photoRequests.get(key);
      if (!slot.isConnected || view !== generation) return;
      if (/^(first|renew|invalid)$/.test(result.state)) return statePage(result.state);
      if (typeof result.photo === 'string' && /^data:image\/jpeg;base64,[A-Za-z0-9+/=]+$/.test(result.photo)) {
        const image = slot.querySelector('img');
        image.src = result.photo;
        image.hidden = false;
        slot.querySelector('.photo-fallback').hidden = true;
        return;
      }
    } catch (_) {
      // Display the fallback after the request fails.
    }
    if (slot.isConnected && view === generation) {
      slot.querySelector('.photo-fallback').textContent = 'الصورة غير متاحة · Image unavailable';
    }
  };
  if (!('IntersectionObserver' in window)) {
    scope.querySelectorAll('[data-villa]').forEach(load);
    return;
  }
  const observer = new IntersectionObserver(entries => {
    for (const entry of entries) {
      if (!entry.target.isConnected || entry.isIntersecting) observer.unobserve(entry.target);
      if (entry.target.isConnected && entry.isIntersecting) load(entry.target);
    }
  }, {rootMargin:'100px'});
  scope.querySelectorAll('[data-villa]').forEach(slot => observer.observe(slot));
}

function changePhoto(button) {
  const count = detailVilla.photoCount;
  photo = button.dataset.photo !== undefined ? Number(button.dataset.photo) :
    (photo + Number(button.dataset.step) + count) % count;
  const hero = document.querySelector('#hero');
  hero.innerHTML = photoSlot(detailVilla, photo, 'hero', 'صورة ' + (photo + 1) + ' للفيلا');
  document.querySelector('#photo-count').textContent = (photo + 1) + ' / ' + count;
  screen.querySelectorAll('[data-photo]').forEach(item =>
    item.setAttribute('aria-pressed', String(Number(item.dataset.photo) === photo)));
  hydratePhotos(hero);
}

function saveRoute(page, id, replace) {

  if (currentRoute?.page === page && currentRoute?.id === id) return;
  const route = { page, id };
  history[replace || !currentRoute ? 'replaceState' : 'pushState'](route, '');
  currentRoute = route;
}

async function navigate(page, id = '', fromHistory = false) {
  if (busy) return;
  busy = true;
  const initial = page === 'start' || page === 'activate';
  screen.setAttribute('aria-busy', 'true');
  const status = document.querySelector('#connection-status');
  status.textContent = '';
  try {
    let result;
    if (page === 'start') page = 'areas';
    if (page === 'activate') {
      result = await rpc('activateAccess');
      if (result.state !== 'active') return statePage(result.state);
      page = 'areas';
    }
    if (page === 'areas') result = await rpc('listAreas');
    if (page === 'list') result = await rpc('listVillas', id);
    if (page === 'villa') result = await rpc('villaDetails', id);
    if (result.state !== 'active') return statePage(result.state);
    if (page === 'areas') areasPage(result.areas);
    if (page === 'list') listPage(id, result.villas);
    if (page === 'villa') details(result.villa);
    if (!fromHistory) saveRoute(page, id, initial);
  } catch (_) {
    status.textContent = 'تعذّر تحميل البيانات. حاول مرة أخرى. · Could not load data. Please try again.';
    if (!screen.firstElementChild) render(nav('start','حاول مرة أخرى','Try again'));
  } finally {
    busy = false;
    screen.removeAttribute('aria-busy');
    if (pendingHistory) {
      const route = pendingHistory;
      pendingHistory = null;
      navigate(route.page, route.id, true);
    }
  }
}

screen.addEventListener('click', event => {
  const button = event.target.closest('button');
  if (!button || busy) return;
  if (button.hasAttribute('data-accept')) navigate('activate');
  else if (button.dataset.page) navigate(button.dataset.page, button.dataset.id);
  else if (detailVilla && (button.dataset.photo !== undefined || button.dataset.step)) changePhoto(button);
});

function start() {
  token = new URLSearchParams((location.hash || '').replace(/^#/, '')).get('t') || '';
  if (!/^[a-f0-9]{32}$/.test(token)) return statePage('invalid');
  window.addEventListener('popstate', event => {
    const route = event.state;
    if (!route || !['areas', 'list', 'villa'].includes(route.page)) return;
    currentRoute = route;
    if (busy) pendingHistory = route;
    else navigate(route.page, route.id, true);
  });
  navigate('start');
}
start();
